using System.IO; using UnityEngine; namespace Reflectable { public sealed class SaveManager { readonly string path=Path.Combine(Application.persistentDataPath,"reflectable_save.json"); public bool HasRun=>File.Exists(path); public void Save(SaveData d){d.valid=true;File.WriteAllText(path,JsonUtility.ToJson(d));} public SaveData Load()=>HasRun?JsonUtility.FromJson<SaveData>(File.ReadAllText(path)):null; public void Clear(){if(HasRun)File.Delete(path);} } }
